package dev.eugheist.ttmodern;
final class RecallWorldClientAudit {
 static boolean saved,checked,useKey,gravity,flying;static int expected,fxBefore;
 static net.minecraft.world.item.ItemStack[] hotbar;
 static net.minecraft.world.item.ItemStack held;static net.minecraft.world.phys.Vec3 position;static float yaw,pitch;
 static net.minecraft.world.level.GameType mode;static net.minecraft.world.level.block.state.BlockState old;
 static final net.minecraft.core.BlockPos DEST=new net.minecraft.core.BlockPos(12,290,12);
 static void restore(net.minecraft.client.Minecraft mc){if(!saved)return;mc.options.keyUse.setDown(useKey);var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.stopUsingItem();p.serverLevel().setBlockAndUpdate(DEST,old);for(int i=0;i<9;i++)p.getInventory().setItem(i,hotbar[i]);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,held);p.setGameMode(mode);p.setNoGravity(gravity);p.getAbilities().flying=flying;p.onUpdateAbilities();p.teleportTo(position.x,position.y,position.z);p.setYRot(yaw);p.setXRot(pitch);p.inventoryMenu.broadcastChanges();saved=false;}
 static void tick(net.minecraft.client.Minecraft mc,int t){
  if(t==1860){fxBefore=WarpGateFx.attempted;WarpGateFx.Sparkle.audit(mc.level);useKey=mc.options.keyUse.isDown();mc.getSingleplayerServer().submit(()->{
   var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());held=p.getMainHandItem().copy();hotbar=new net.minecraft.world.item.ItemStack[9];for(int i=0;i<9;i++)hotbar[i]=p.getInventory().getItem(i).copy();position=p.position();yaw=p.getYRot();pitch=p.getXRot();mode=p.gameMode.getGameModeForPlayer();gravity=p.isNoGravity();flying=p.getAbilities().flying;old=p.serverLevel().getBlockState(DEST);EnchanterClientAudit.check(p.serverLevel().getBlockEntity(DEST)==null,"recall fixture has no existing tile");saved=true;
   p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setNoGravity(true);p.teleportTo(8.5,291,8.5);p.setYRot(20);p.setXRot(10);p.serverLevel().setBlockAndUpdate(DEST,WarpGateBlock.BLOCK.get().defaultBlockState());for(int i=0;i<9;i++)p.getInventory().setItem(i,net.minecraft.world.item.ItemStack.EMPTY);
   var wand=dev.eugheist.tc4modern.WandParts.make(dev.eugheist.tc4modern.WandParts.CAPS.get("gold"),dev.eugheist.tc4modern.WandParts.RODDEFS.get("silverwood"));dev.eugheist.tc4modern.FociContent.setFocus(wand,new net.minecraft.world.item.ItemStack(RecallFocus.ITEM.get()));for(var a:new thaumcraft.api.aspects.Aspect[]{thaumcraft.api.aspects.Aspect.AIR,thaumcraft.api.aspects.Aspect.EARTH,thaumcraft.api.aspects.Aspect.ORDER})dev.eugheist.tc4modern.WandData.add(wand,a,80,true);expected=dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.AIR)-(int)(4000*Math.max(dev.eugheist.tc4modern.WandData.craftingModifier(wand,p,thaumcraft.api.aspects.Aspect.AIR),.1f));p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,wand);var pearl=new net.minecraft.world.item.ItemStack(SkyPearl.ITEM.get());SkyPearlData.bind(pearl,DEST,p.level().dimension().location());p.getInventory().setItem((p.getInventory().selected+1)%9,pearl);p.inventoryMenu.broadcastChanges();
  }).join();}
  if(t==1880){EnchanterClientAudit.check(dev.eugheist.tc4modern.FociContent.getFocusItem(mc.player.getMainHandItem()).is(RecallFocus.ITEM.get()),"recall inventory network sync");mc.options.keyUse.setDown(true);mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);}
  if(t>=1900&&t<1940)EnchanterClientAudit.check(mc.player.getX()<10,"recall does not teleport before cast delay");
  if(t>=1945&&!checked&&Math.abs(mc.player.getX()-12.5)<.001){EnchanterClientAudit.check(WarpGateFx.attempted-fxBefore==40,"original teleport calls twenty sparkles before and after");mc.options.keyUse.setDown(false);mc.gameMode.releaseUsingItem(mc.player);mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());try{EnchanterClientAudit.check(Math.abs(p.getY()-291.6)<.001&&Math.abs(p.getZ()-12.5)<.001,"actual recall centered destination");EnchanterClientAudit.check(dev.eugheist.tc4modern.WandData.get(p.getMainHandItem(),thaumcraft.api.aspects.Aspect.AIR)==expected,"one success cost");EnchanterClientAudit.check(p.getInventory().getItem((p.getInventory().selected+1)%9).is(SkyPearl.ITEM.get()),"recall retains pearl");checked=true;System.out.println("TT RECALL WORLD CLIENT AUDIT: ALL PASS (actual held-use network/cast delay,native movement,success-only discounted vis,pearl conservation,restored fixture)");}finally{restore(mc);}}).join();}
 }
}
